/// Reads one component description for [locale] (English fallback).
String docsComponentDescription(String id, Locale locale) {
  return docsContentComponent(locale, 'cmpDesc_$id');
}

/// Reads one content string for [locale] (English fallback).
String docsContentComponent(Locale locale, String key) {
  final String tag = docsLocaleTag(locale);
  final Map<String, String>? table = _values[tag];
  final String? value = table?[key];
  if (value != null) {
    return value;
  }
  return _values['en']![key] ?? key;
}

